// Kontrollerar migrationen för social_posts (SM-05, k-038): kolumner, grindspärr, radskydd.
// Statisk kontroll av SQL-filen; själva avvisningen prövas i databasen efter körning (se filens sista rader).
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const sql = fs.readFileSync('supabase/002_social_posts.sql', 'utf8');
const kod = sql.replace(/--.*$/gm, '');
const kolumner = ['id', 'varumarke', 'kanal', 'pelare', 'text', 'ai_markning', 'granskare', 'barken_status',
  'rattighetsstatus', 'utm', 'planerad_tid', 'status', 'skapad', 'uppdaterad'];
const sparr = (kod.match(/constraint social_posts_grindsparr check \(([\s\S]*?)\n  \)/) || [])[1] || '';
const krav = {
  allaKolumner: kolumner.every((k) => new RegExp('\\n  ' + k + '\\s+(uuid|text|timestamptz)').test(kod)),
  standardUtkast: /barken_status\s+text not null default 'utkast'/.test(kod) && /\n  status\s+text not null default 'utkast'/.test(kod),
  standardOklar: /rattighetsstatus\s+text not null default 'oklar'/.test(kod),
  sparrStatus: /status not in \('schemalagd','publicerad'\)/.test(sparr),
  sparrBarken: /barken_status = 'godkand'/.test(sparr),
  sparrRattighet: /rattighetsstatus in \('klar','ej_tillamplig'\)/.test(sparr),
  sparrGranskare: /granskare is not null/.test(sparr),
  sparrMarkning: /btrim\(ai_markning\) <> ''/.test(sparr),
  radskydd: /alter table public\.social_posts enable row level security/.test(kod),
  ingenOppenPolicy: !/create policy/i.test(kod),
  ingenAnon: /revoke all on public\.social_posts from anon, authenticated/.test(kod),
  ingenRadering: !/\bdrop table\b|\btruncate\b|\bdelete from\b/i.test(kod),
  rorBaraSocialPosts: !/public\.docs\b/.test(kod),
  signatur: sql.includes('Generated by AI, Directed by MS'),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
